34	 * Redirect di sicurezza dalla "home" di Fortify
35	 * per route che usano il middleware "verified"
36	 * (che potrebbe reindirizzare proprio a "home")
37	 * Registro un redirect per avere più fliessibilità
38	 * nella gestione (anzichè agire sul parametro di config fortify.home)
39	 */
40	Route::get('home', function (Request $request) {
41	    if ($request->user()) {
42	        return redirect(route('download_area'));
