56	/**
57	 * Rotte legacy delle vecchie basi ("/prodotti" it, "/products" en/us) e "/kaleido",
58	 * verso la nuova base "/collezioni" (it) / "/collections" (en/us).
59	 * Le rotte categoria/dettaglio puntano al dispatcher, che emette il 301 verso l'URL canonico
60	 * (categorie via request_url/revision, prodotti via full_page_url); ricerca e kaleido sono
61	 * redirect diretti con preservazione del path.
62	 */
63	$legacyCollections = [
64	    ['locale' => 'it', 'old' => 'prodotti', 'new' => 'collezioni', 'search' => 'ricerca'],
65	    ['locale' => 'en', 'old' => 'products', 'new' => 'collections', 'search' => 'search'],
66	    ['locale' => 'us', 'old' => 'products', 'new' => 'collections', 'search' => 'search'],
67	];
68	foreach ($legacyCollections as $c) {
69	    Route::get("{$c['locale']}/{$c['old']}/{$c['search']}", fn () => redirect("/{$c['locale']}/{$c['new']}/{$c['search']}", 301));
70	    Route::get("{$c['locale']}/{$c['old']}/{categoryTree}", [ProductsController::class, 'dispatcher'])
71	        ->where('categoryTree', '([a-zA-Z0-9\/\-]+)');
72	    Route::get("{$c['locale']}/kaleido/{rest?}", fn ($rest = null) => redirect("/{$c['locale']}/{$c['new']}/kaleido".($rest ? '/'.$rest : ''), 301))
73	        ->where('rest', '.*');
74	}
