<?php

namespace App\Http\Controllers;

use App\Models\Banner;
use App\Models\Bespoke;
use App\Models\History;
use App\Models\News;
use App\Models\Page;
use App\Models\Portfolio;
use App\Models\Prodcat;
use AtrioTeam\Marvin\App\Localization\LangManager;

class PagesController extends Controller
{
    /**
     * Homepage
     */
    public function homepage(LangManager $langManager)
    {
        // load banners list
        $banners = Banner::where('page', 'homepage')->listbyLang($langManager->lgId())->get();

        // load categories
        $categories = Prodcat::roots()->listByLang($langManager->lgId())->get();

        // load portfolios
        $portfolios = Portfolio::with('category')->with('galleries', fn ($query) => $query->byType('img_1'))->listByLang($langManager->lgId())->get();

        // load latest news
        $news = News::with('category')->listByLang($langManager->lgId())->where('highlight', 'Y')->limit(2)->get();

        return view("homepage", compact('banners', 'categories', 'portfolios', 'news'));
    }


    /**
     * Vetro
     */
    public function glass(LangManager $langManager)
    {
        // load contents
        $page = Page::whereCode('glass')->listbyLang($langManager->lgId())->with('galleries', fn ($query) => $query->byLang($langManager->lgId()))->firstOrFail();

        return view('company.vetro', compact('page'));
    }


    /**
     * Azienda
     */
    public function company(LangManager $langManager)
    {
        // load contents
        $page = Page::whereCode('company')->listbyLang($langManager->lgId())->with('galleries', fn ($query) => $query->byLang($langManager->lgId()))->firstOrFail();

        // load history's contents
        $historyPage = Page::whereCode('history')->listbyLang($langManager->lgId())->with('galleries', fn ($query) => $query->byLang($langManager->lgId()))->firstOrFail();

        return view('company.azienda', compact('page', 'historyPage'));
    }


    /**
     * Bespoke
     */
    public function bespoke(LangManager $langManager)
    {
        // load contents
        $page = Page::whereCode('bespoke')->listbyLang($langManager->lgId())->with('galleries', fn ($query) => $query->byLang($langManager->lgId()))->firstOrFail();

        return view('company.bespoke', compact('page'));
    }
}

