/**
 * Ricerca prodotti
 * Per criteri di ricerca:
 * - v.mail Stefano Traverso del 2022/12/22 15:11
 * - update agosto 2024 "vorrebbero poter cercare per tipologia (es sospensione, tavolo, ecc)" => ricerca per nome della categoria
 * - update dicembre 2024  aggiungerei dunque gli elementi kaleido (per nome) e le composizioni kaleido (per nome o codice)
 */
public function search(Request $request, LangManager $langManager, SearchService $searchService, MarvinRouter $LangRouter)
{
    try {
        $request->validate([
            'q' => 'required|string|max:50',
        ]);
    } catch (\Illuminate\Validation\ValidationException $e) {
        abort(400, 'Invalid search query');
    }

    // stringa di ricerca
    $q = $request->q;

    // esegui ricerca e isola i risultati unici
    $results = $searchService->search($q, app()->getLocale())->unique(fn (SearchIndex $index) => $index->searchable_type.$index->searchable_id);
    $results = $results->pluck('searchable')->filter(function ($item) {

        // le condizioni successive si applicano solo alle varianti di prodotto
        if (!$item instanceof ProductVariant) {
            return true;
        }
        // e.g. if parent was deleted
        return $item->parent !== null && $item->parent->isPublished();

