/**
 * Aggiunge al breadcrumb l'albero delle categorie prodotto.
 *
 * @param array<int, Prodcat> $categories dalla radice alla più profonda
 */
protected function pushCategoriesBreadcrumb(array $categories): void
{
    $breadcrumbs = app(Breadcrumbs::class);

    foreach ($categories as $index => $category) {
        $lang = $category->current_lang;

        /**
         * Il primo livello è la collezione (il "title" da solo, es. "Contemporanea",
         * non è autoesplicativo, per cui viene prefissato come nell'h1 della pagina).
         * I livelli successivi sono le tipologie, per le quali "list_h1" è l'etichetta
         * discorsiva compilata da cms; se manca ripiego sul "title".
         */
        $name = $index === 0
            ? trim(__('global.collezione').' '.$lang->title)
            : ($lang->list_h1 ?: $lang->title);

        $breadcrumbs->push((string) $name, $lang->request_url);
    }
}


