=== main.scss
// import di base e personalizzazione uikit 
@import "_common.scss";

// fonts
@import "_fonts.scss";

// 4. Import UIkit.
@import "../../node_modules/uikit/src/scss/uikit-theme.scss";

// componenti
@import "_components.scss";


/*
* --------------------------------------------------------------------------------------------------------
* Css base
* --------------------------------------------------------------------------------------------------------
*/

/*
* --------------------------------------------------------------------------------------------------------
* GENERALI
* --------------------------------------------------------------------------------------------------------
*/
body {
    background: $col-bianco;
    font-family: 'italamp-sansSerif', sans-serif;
    color: $base-color;
    -webkit-font-smoothing: antialiased;
    transition: background-color 1s ease-in-out;
    will-change: background-color;

    min-height: 100vh;
    min-height: fill-available;
    min-height: -webkit-fill-available;


    &.negative{
        //background: $col-nero;
    }
}

html {
    height: fill-available;
    height: -webkit-fill-available;
}

// fix per locomotive scroll
html.has-scroll-smooth
{
    overflow: hidden;
    position: fixed;
    left: 0;
    right: 0;
    top: 0;
    bottom: 0;  
}

//
html.has-scroll-scrolling{
    iframe{
        pointer-events:none;
    }
}

em {color: inherit;}



a label{
    cursor: pointer;
}

 //btn 
 .uk-button{
     display: inline-block;
     padding: 15px 25px;

    &.uk-button-default{
        background-color: $col-nero;
        border: 1px solid $col-nero;
        color:$col-bianco;
        transition: opacity .5s ease-in-out;
        will-change: opacity;
        &:hover{
            opacity: .8;
        }
    }

    &.uk-button-primary{
        letter-spacing: 1px;
        border: 1px solid $col-bianco;
        background-color: transparent;
        &:hover{
            border-color:rgba(255,255,255,.5);
        }
    }
    &.uk-button-secondary{
        letter-spacing: 1px;
        transition: background .5s ease-in-out;
        will-change: background;
        background-color: rgba(255,255,255,.8);
        color: $col-nero;
        &:hover{
            background-color: $col-bianco;
        }
    }


 } 


h2, .uk-h2,
h3, .uk-h3,
h4, .uk-h4,
h5, .uk-h5,
h6, .uk-h6,
.uk-heading-small,
.uk-heading-medium,
.uk-heading-large,
.uk-heading-xlarge,
.uk-heading-2xlarge {
    @include headingBase();
}


/*
* --------------------------------------------------------------------------------------------------------
* //// GENERALI
* --------------------------------------------------------------------------------------------------------
*/

header {
    pointer-events: none;
    position: fixed;
    transition: background .3s ease-in-out .5s;
    will-change: background;
    top: 0;
    left: 0;
    z-index: 11;
    width: 100%;
    padding-top:15px;
    padding-bottom:15px;

    @media (min-width: $breakpoint-locomotive) {
        position: absolute;
        padding-top:30px;
    }
    @media (min-width: $breakpoint-large) {
        padding-top:40px;
    }
    .maxWidth{
        max-width: unset;
    }
    a{
        pointer-events: auto;
    }
    >div{
        z-index: 2;
        @media (max-width: $breakpoint-medium-max) {
            width: calc(100% - 30px)!important;
        }

        .logo{
            svg{
                width: 128px;
                height: 41px;
                @media (min-width: $breakpoint-locomotive) {
                    width: 162px;
                    height: 52px;
                }
                @media (min-width: $breakpoint-large) {
                    width: 186px;
                    height: 60px;
                }
                path{
                    transition: fill .3s ease-in-out;
                    will-change: fill;
                }
                g#alamp{
                    opacity: 1;
                    transition: opacity .3s ease-in-out;
                    will-change: opacity, z-index;
                }
            }
        }
        .iconMenu{
            text-align: right;

            li.item{
                margin-top: 3px;
                @media (min-width: $breakpoint-locomotive) {
                    margin-top: 10px;
                }

                &:not(:last-child) {border-right: 1px solid rgba(0,0,0,0.25);}

                padding-left: 10px;
                padding-right: 10px;
                @media (min-width: $breakpoint-small) {
                    padding-left: 20px;
                    padding-right: 20px;
                }

                a{
                    line-height: 35px;
                    display: inline-block;
                    font-size: 13px;
                    letter-spacing: 1px;
                    text-transform: uppercase;
                }


                &.language{

                    @media (min-width: 500px) {
                        position: relative;
                    }
                    svg{
                        margin-top: -2px;
                        margin-left: 3px;
                    }
                    //con menu aperto nascondo
                    body.menu &{
                        display: none;
                    }

                    //palette scelta lingua / country
                    .palette-languages{
                        display: none;
                        pointer-events: auto;
                        position: absolute;
                        z-index: 1020;
                        -webkit-box-sizing: border-box;
                        box-sizing: border-box;
                        background: $col-bianco;
                        box-shadow: 0 5px 12px rgb(0 0 0 / 15%);
                        left:3vw;
                        width: 90vw;
                        padding: 25px 15px;
                        @media (min-width: 500px) {
                            padding: 25px;
                            left: unset;
                            right: 10px;
                            width: 360px;
                        }
                        &.visibile{
                            display: block;
                        }
                        //lingue
                        .languages{                            
                            text-align: left;
                            padding: 0;
                            li{
                                opacity: .3;
                                display: block;
                                a{
                                    color: $col-nero!important;
                                    @include a-underline($col-nero);
                                    line-height: 22px!important;
                                }
                                &.uk-active{
                                    opacity: 1;
                                }
                            }
                        }

                    }
                    .country{
                        text-align: left;
                        border-top: 1px solid $col-nero;
                        padding-top: 25px;
                        a{
                            display: inline-block;

                            //testo international, US
                            span.txt{
                                color: $col-nero!important;
                                opacity: .3;
                                line-height: 22px!important;
                                margin-left: 10px;
                            }
                            &.active{
                                span.txt{
                                    opacity: 1;
                                    margin-left: 0;
                                    margin-right: 10px;
                                }
                            }

                            //switch
                            label.switch{
                                position: relative;
                                display: inline-block;
                                width: 38px;
                                height: 22px;
                                transform: translateY(7px);
                                margin-left: 10px;
                                margin-right: 10px;

                                .slider {
                                    position: absolute;
                                    top: 0;
                                    left: 0;
                                    right: 0;
                                    bottom: 0;
                                    background-color: #C4C4C4;
                                    -webkit-transition: .4s;
                                    transition: .4s;
                                    border-radius: 34px;
                                    &:before {
                                        position: absolute;
                                        content: "";
                                        height: 18px;
                                        width: 18px;
                                        left: 2px;
                                        bottom: 2px;
                                        background-color: $col-nero;
                                        -webkit-transition: .4s;
                                        transition: .4s;
                                        border-radius: 50%;
                                    }
                                }

                            }


                            &:hover{
