                                        }
                                    }
                                }
                            }
                        }


                    //se è attiva la country US, sposto lo switch
                    &.us{
                        label.switch {
                            .slider{
                                &:before{
                                    transform: translateX(16px);
                                }

                            }
                        }
                        &:hover{
                            label.switch .slider:before {
                                transform: translateX(12px);        
                            }
                        }
                    }
                }


                } // language

                &.menuToggler{

