                                    &.default{
                                        display: none;
                                    }
                                    &.close{
                                        display: inline-block;
                                    }
                                }
                            }    
                        }
                        svg{
                            margin-top: -3px;
                            margin-left: 6px;
                            &.default{
                                display: inline-block;
                            }
                            &.close{
                                display: none;
                            }
                            body.menu &{
                                &.default{
                                    display: none;
                                }
                                &.close{
                                    display: inline-block;
                                }
                            }
                        }
                    }
                }  // menuToggler
                &.search{
                    display: inline-block;
                    opacity: 1;
                    padding-right: 20px;
