                    }

                    //nascondo con ricerca aperta
                    body.search &{
                        display: none;
                    }
                } // search

                //preferiti
                &.favorites{
                    display: none;
                    opacity: 0;
                    transition: opacity 1s ease-in-out;
                    will-change: opacity;

                    //visualizzo se c'è class visibile e il menu è aperto
                    body.menu &.visibile {
                        display: inline-block;
                        opacity: 1;                        
