                            margin-top: -2px;
                            margin-left: 3px;
                        }
                        //label ricerca prodotto visibile su desk e tablet 
                        label{
                            display: none;
                            @media (min-width: $breakpoint-medium) {
                                display: inline-block;
                            }
                        }

                    }

                    //nascondo con ricerca aperta
                    body.search &{
                        display: none !important;
                    }
                }

                &.download{
                    display: none;
                    opacity: 0;
                    transition: opacity 1s ease-in-out;
                    will-change: opacity;

                    //visualizzo se c'è class visibile e il menu è aperto
                    body.menu & {
                        @media (min-width: $breakpoint-small) {
                            display: inline-block;
                            opacity: 1;
                        }
                        img{
                            margin-top: -2px;
                            margin-left: 3px;
                            height: 1.2em;
                        }
                        //label ricerca prodotto visibile su desk e tablet 
                        label{
                            display: none;
                            @media (min-width: $breakpoint-medium) {
                                display: inline-block;
                            }
