                        }
                    }
                }
            }
        }



    }
    //se la pagina non è al top:0, nascondo parte del logo 
    body:not(.menu).scrolling &{
        .logo{
            svg{
                g#alamp{
                    opacity: 0;
                }
            }
        }



    }

    //solo su mobile
