    @media (max-width: $breakpoint-small-max) {


        //rimuovo le transizioni
        transition:none!important;
        *{
            transition: none!important;
        }
        .logo{
            svg{
                g{
                    opacity: 1!important;
                }
            }
        }



        //e allo scroll, forzo il menu in positivo 
        body.scrolling &{
            background-color: $col-bianco;
