                        color: $col-nero!important;
                    }
                    svg:not(.ricerca){
                        *{
                            fill: $col-nero!important;
                        }
                    }
                    svg.ricerca{
                        *{
                            fill: transparent;
                            stroke: $col-nero!important;
                        }
                    }
                }
            }
        }

    }

