[data-namespace="kaleido-composition-detail"] {
    .titolo-intro{
        position: relative;
        display: block;
        background-image: url("../../public/img/kaleido/mobile-bg.webp");
        background-size: cover;
        background-repeat: no-repeat;
        background-position: center;
        @media (min-width: $breakpoint-medium) {
            background-image: url("../../public/img/kaleido/desk-bg.webp");
        }
        &:before{
            content: "";
            width: 100%;
            height: 50%;
            position: absolute;
            bottom: 0;
            left: 0;
            z-index: 1;
            background: linear-gradient(360deg, #FFFFFF 15.19%, rgba(255, 255, 255, 0) 101.81%);
        }
        h1,h2,h3{
            position: relative;
            z-index: 2;
        }
    }
